const reviewInput = z
  .object({
    status: z.enum(['keep', 'revise', 'defer']),
    reason: z.string().trim().min(1, 'Add a reason for your decision.').max(4000),
  })
  .strict();

async function saveReview() {
  if (
    !detail ||
    !selected ||
    busy ||
    loading ||
    !draft.status ||
    !reviewDraftState(draft, review).canSave
  )
    return;
  setBusy(true);
  setError('');
  setNotice('');
  setReviewFailure(undefined);
  try {
    const saved = await api<ChangeDetail>(
      `/api/changes/${detail.change.id}/reviews/${selected.item.id}`,
      { method: 'PUT', body: JSON.stringify(draft) },
    );
    setDetail(saved);
    setDrafts((entries) => {
      const next = { ...entries };
      delete next[draftKey];
      return next;
    });
    setNotice({ item: selected.item, status: draft.status });
    return saved;
  } catch (e) {
    setReviewFailure({ key: draftKey, message: (e as Error).message });
  } finally {
    setBusy(false);
  }
}

const reviewPath = `/api/changes/${saved.change.id}/reviews/${prepared.items[fixture.review.item]}`;
const reviewInput = { status: fixture.review.status, reason: fixture.review.reason };
await api.request<Review>(reviewPath, 'PUT', reviewInput);
await api.request<Review>(reviewPath, 'PUT', reviewInput);

export function prepareJudgeSnapshot(base: string) {
  mkdirSync(base, { recursive: true });
  const directory = mkdtempSync(join(base, 'ripple-judge-'));
  const writer = mkdtempSync(join(tmpdir(), 'ripple-evaluation-'));
  try {
    const validation = runPhase('write', writer, judgeCase);
    // runPhase is synchronous: the only writer has exited before copying native files.
    copyTree(writer, join(directory, 'snapshot'));
    const { fixture, fixtureHash } = loadCase(judgeCase);

export function runPhase(
  mode: 'write' | 'read' | 'prepare',
  directory: string,
  caseName: CaseName = 'async-owner',
) {
  loadCase(caseName);
  const child = spawnSync(
    process.execPath,
    [
      '--import',
      'tsx',
      fileURLToPath(new URL('./worker.ts', import.meta.url)),
      mode,
      directory,
      caseName,
    ],
    {
      encoding: 'utf8',
      timeout: 30000,
    },
  );
  if (child.status !== 0)
    throw new Error(
      child.stderr || child.stdout || child.error?.message || 'Evaluation worker failed',
    );
  return JSON.parse(child.stdout.trim()) as {
    ok: boolean;
    phase: string;
    case: string;
    fixtureSha256: string;
    scores: ReturnType<typeof scoreImpact>[];
  };
}

